import { pesquisarAcervo, normalizar, fontesCatalogo } from './provedores/agregador.js';
import { iniciarCenario } from './cenario.js';
const $=(s,r=document)=>r.querySelector(s);
const lerSalvo=(chave,padrao)=>{try{return JSON.parse(localStorage.getItem(chave))??padrao}catch{return padrao}};
const gravar=(chave,valor)=>{try{localStorage.setItem(chave,JSON.stringify(valor));return true}catch{return false}};
const escapar=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const linkSeguro=u=>{if(typeof u!=='string'||!u.trim())return '';try{const p=new URL(u,location.origin);return ['http:','https:'].includes(p.protocol)?p.href:''}catch{return ''}};
const img=(u,cls='capa',alt='')=>linkSeguro(u)?`<img class="${cls}" src="${escapar(linkSeguro(u))}" alt="${escapar(alt)}" loading="lazy" referrerpolicy="no-referrer">`:'<div class="sem-capa" aria-label="Capa não fornecida pela fonte">L</div>';
const estado={catalogo:[],destaques:[],livros:[],resultados:[],consulta:'',pagina:1,token:0,erros:[],porFonte:{},temMais:false,buscando:false,leitura:null,leituraToken:0,restaurando:false,fonte:lerSalvo('bl:fonte',21),progresso:lerSalvo('bl:progresso',{}),acervo:lerSalvo('bl:acervo',[]),perfil:lerSalvo('bl:perfil',null),pausado:lerSalvo('bl:pausado',matchMedia('(prefers-reduced-motion: reduce)').matches),qualidade:lerSalvo('bl:qualidade','equilibrado'),audio:null,progressoFontes:null};
if(!Array.isArray(estado.acervo))estado.acervo=[];
if(!estado.progresso||typeof estado.progresso!=='object')estado.progresso={};
const temas={ficcao:{nome:'Ficção',busca:'fiction'},filosofia:{nome:'Filosofia',busca:'philosophy'},ciencia:{nome:'Ciência',busca:'science'},politica:{nome:'Política',busca:'politics'},natureza:{nome:'Natureza',busca:'nature'},poesia:{nome:'Poesia',busca:'poetry'}};
const cenario=iniciarCenario({pausado:estado.pausado,qualidade:estado.qualidade});
function aviso(texto){const d=document.createElement('div');d.className='aviso';d.textContent=texto;const modal=[...document.querySelectorAll('dialog[open]')].at(-1);if(modal){let a=$('.avisos',modal);if(!a){a=document.createElement('div');a.className='avisos';a.setAttribute('role','status');modal.append(a)}a.append(d)}else $('#avisos').append(d);setTimeout(()=>d.remove(),4200)}
function abrir(id){const d=$('#'+id);if(!d.open)d.showModal();if(id==='painel')d.scrollTop=0;cenario.suspender(true)}
function fechar(id){$('#'+id).close();cenario.suspender(Boolean(document.querySelector('dialog[open]')))}
for(const d of document.querySelectorAll('dialog')){d.addEventListener('close',()=>{cenario.suspender(Boolean(document.querySelector('dialog[open]')));if(d.id==='leitor'){salvarLeitura();estado.leituraToken++}});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)fechar(d.id)})}
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){e.target.classList.add('capa-falhou');e.target.alt='Capa indisponível';e.target.removeAttribute('src')}},true);
function atualizarPerfil(){const nome=estado.perfil?.nome;$('#nome-perfil-topo').textContent=nome?nome.split(' ')[0]:'Meu perfil';$('#total-acervo').textContent=estado.acervo.length}
function definirPausa(valor){estado.pausado=valor;gravar('bl:pausado',valor);document.documentElement.classList.toggle('pausado',valor);$('#botao-movimento').setAttribute('aria-pressed',String(valor));$('#botao-movimento').setAttribute('aria-label',valor?'Retomar animações':'Pausar animações');$('#botao-movimento').textContent=valor?'▷':'Ⅱ';cenario.pausar(valor)}
definirPausa(estado.pausado);atualizarPerfil();
const carregamento=Promise.all([fetch('/data/catalogo.json',{credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('/data/destaques.json',{credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error();return r.json()})]).then(([c,d])=>{estado.catalogo=Array.isArray(c)?c:[];estado.destaques=Array.isArray(d)?d:[]}).catch(()=>aviso('Não foi possível carregar a seleção local. A pesquisa externa continua disponível.'));
function opcoes(){return{pagina:estado.pagina}}
function locais(q){const termo=normalizar(q);return estado.catalogo.filter(l=>!termo||termo.split(/\s+/).filter(Boolean).every(t=>normalizar([l.titulo,...l.autores,...(l.palavras||[]),...(l.categorias||[])].join(' ')).includes(t)))}
async function abrirBusca(q=''){await carregamento;$('#campo-busca').value=q;abrir('busca');executarBusca(q);$('#campo-busca').focus()}
function prepararCarregamento(total,mais=false){estado.progressoFontes={total:Math.max(1,total||fontesCatalogo.length),concluidas:0,ultima:mais?'Buscando novas páginas nas fontes que ainda têm resultados.':'Abrindo as primeiras estantes.',mais};atualizarCarregamento()}
function atualizarCarregamento(info){if(info&&estado.progressoFontes){estado.progressoFontes.concluidas=Math.max(estado.progressoFontes.concluidas,info.concluidas||0);estado.progressoFontes.ultima=info.ok?`${info.nome} respondeu${info.quantidade?` com ${info.quantidade} resultado${info.quantidade===1?'':'s'}`:' sem correspondências nesta página'}.`:`${info.nome} não respondeu nesta tentativa. Continuando nas outras fontes…`;estado.progressoFontes.total=Math.max(1,info.total||estado.progressoFontes.total)}const p=estado.progressoFontes;if(!p)return;const pct=Math.min(100,Math.round((p.concluidas/p.total)*100));const caixa=$('#carregando-busca');if(caixa){caixa.classList.toggle('mais',Boolean(p.mais));$('#carregando-titulo').textContent=p.mais?'Ainda há estantes para percorrer…':'Percorrendo bibliotecas, universidades e arquivos…';$('#carregando-fonte').textContent=p.ultima;$('#progresso-fontes-barra').style.width=pct+'%';$('#progresso-fontes-texto').textContent=`${p.concluidas} de ${p.total} fontes consultadas`}}
function intercalarFontes(lista){
 const ordem=['curadoria',...fontesCatalogo.map(f=>f.id)],grupos=new Map();
 for(const l of lista){const id=l.curadoria?'curadoria':(l.fonte||'outra');if(!grupos.has(id))grupos.set(id,[]);grupos.get(id).push(l)}
 const ids=[...ordem.filter(id=>grupos.has(id)),...[...grupos.keys()].filter(id=>!ordem.includes(id))],saida=[];let i=0,adicionou=true;
 while(adicionou){adicionou=false;for(const id of ids){const item=grupos.get(id)?.[i];if(item){saida.push(item);adicionou=true}}i++}
 return saida;
}
function renderizar(){
 let lista=intercalarFontes([...estado.livros]);
 estado.resultados=lista;
 const mostra=lista,contagens={};for(const l of lista){const id=l.curadoria?'curadoria':l.fonte;contagens[id]=(contagens[id]||0)+1}
 const estados=fontesCatalogo.map(f=>({id:f.id,nome:f.nome,dados:estado.porFonte[f.id],quantidade:contagens[f.id]||0})),responderam=estados.filter(x=>x.dados&&!x.dados.erro).length;
 const falhas=estado.erros.length?` · ${estado.erros.length} fonte${estado.erros.length===1?'':'s'} indisponível${estado.erros.length===1?'':'is'} nesta tentativa`:'';
 const andamento=estado.buscando?' · pesquisa em andamento':'';
 $('#status-busca').textContent=`${lista.length} ${lista.length===1?'resultado encontrado':'resultados encontrados'}${estado.consulta?` · ${responderam}/${fontesCatalogo.length} fontes responderam`:''}${andamento}${falhas}`;
 const chips=$('#fontes-status');if(chips){chips.hidden=!estado.consulta&&!estado.buscando;chips.innerHTML=(contagens.curadoria?`<span class="fonte-chip ok"><b>Biblioteca</b><i>${contagens.curadoria}</i></span>`:'')+estados.map(x=>`<span class="fonte-chip ${x.dados?.erro?'erro':x.dados?'ok':'espera'}"><b>${escapar(x.nome)}</b><i>${x.dados?.erro?'×':x.dados?x.quantidade:'…'}</i></span>`).join('')}
 const carga=$('#carregando-busca');if(carga){carga.hidden=!estado.buscando;carga.setAttribute('aria-hidden',String(!estado.buscando));carga.classList.toggle('com-resultados',Boolean(estado.buscando&&mostra.length));if(estado.buscando)atualizarCarregamento()}
 $('#resultados').setAttribute('aria-busy',String(estado.buscando));
 const falharamTodas=!estado.buscando&&estado.erros.length>=fontesCatalogo.length;
 const vazioTitulo=estado.buscando?'Abrindo as estantes…':falharamTodas?'As fontes não responderam.':'Nenhuma fonte que respondeu encontrou esse título.';
 const vazioTexto=estado.buscando?`Consultando ${fontesCatalogo.length} fontes abertas de livros, estudos e materiais educacionais.`:falharamTodas?'Isso é uma falha de conexão/API, não significa que o livro não exista. Tente novamente em alguns instantes.':estado.erros.length?'Algumas fontes ficaram indisponíveis nesta tentativa. A biblioteca continuou pesquisando nas demais.':'Tente também título + autor ou ISBN. Nenhum filtro de idioma, assunto ou plataforma está sendo aplicado.';
 $('#resultados').innerHTML=mostra.length?mostra.map((l,i)=>`<article class="resultado">${img(l.capa,'capa','Capa de '+l.titulo)}<div><h3>${escapar(l.titulo)}</h3><p>${escapar(l.autores.join(' · ')||'Autoria na fonte')}</p><div class="meta-livro"><span>${escapar(l.idiomas.map(x=>({pt:'Português',por:'Português',en:'Inglês',eng:'Inglês',es:'Espanhol',spa:'Espanhol',fr:'Francês',fre:'Francês'})[x]||x).join(' / ')||'Idioma não informado')}</span><span>${escapar(l.provedor)}</span><span class="tipo-acesso ${l.acessoLivre?'integral':'catalogo'}">${escapar(l.tipoAcesso|| (l.acessoLivre?'Leitura integral':'Catálogo'))}</span>${l.formatos.filter(f=>['PDF','EPUB'].includes(f.tipo)).map(f=>`<span>${f.tipo}</span>`).join('')}</div><div class="acoes-resultado">${l.ler?`<button class="ler" data-ler="${i}">${l.acessoLivre?'Ler grátis':'Abrir na fonte'} ↗</button>`:''}${l.formatos.filter(f=>['PDF','EPUB'].includes(f.tipo)).slice(0,2).map(f=>`<a href="${escapar(linkSeguro(f.url))}" target="_blank" rel="noopener noreferrer">${f.tipo} ↓</a>`).join('')}<button data-salvar="${i}" class="${estado.acervo.some(x=>x.id===l.id)?'salvo':''}" aria-label="${estado.acervo.some(x=>x.id===l.id)?'Remover':'Guardar'} ${escapar(l.titulo)} no acervo">${estado.acervo.some(x=>x.id===l.id)?'✓ Salvo':'+ Acervo'}</button><button data-ficha="${i}">Detalhes</button></div></div></article>`).join(''):`<div class="estado-vazio"><h3>${vazioTitulo}</h3><p>${vazioTexto}</p>${!estado.buscando?'<button class="secundario" data-ver-selecao>Ver seleção da biblioteca</button>':''}</div>`;
 $('#carregar-mais').hidden=estado.buscando||!estado.temMais;$('#carregar-mais').textContent='Buscar mais resultados em todas as fontes';
}
let renderBuscaPendente=false;
function renderizarBuscaLogo(){if(renderBuscaPendente)return;renderBuscaPendente=true;requestAnimationFrame(()=>{renderBuscaPendente=false;renderizar()})}
async function executarBusca(q,mais=false){
 estado.consulta=q;const token=++estado.token,porFonteAntes=mais?structuredClone(estado.porFonte):{};
 if(!mais){estado.pagina=1;estado.livros=locais(q);estado.erros=[];estado.porFonte={};estado.temMais=false}else estado.pagina++
 const fontesAtivas=mais?Object.entries(estado.porFonte).filter(([,v])=>v?.temMais).map(([id])=>id):undefined;prepararCarregamento(fontesAtivas?.length||fontesCatalogo.length,mais);estado.buscando=true;renderizar();
 if(!q){estado.buscando=false;estado.temMais=false;renderizar();return}
 const aplicarFonte=info=>{
  if(token!==estado.token)return;atualizarCarregamento(info);
  if(Array.isArray(info.livros)&&info.livros.length){const mapa=new Map(estado.livros.map(l=>[l.id,l]));for(const l of info.livros)if(l?.id&&!mapa.has(l.id))mapa.set(l.id,l);estado.livros=[...mapa.values()]}
  if(info.dados){const anterior=mais?porFonteAntes[info.id]:null;estado.porFonte[info.id]={...info.dados,carregados:(anterior?.carregados||0)+(info.dados.carregados||0)}}
  const erros=new Set(estado.erros);if(info.ok)erros.delete(info.id);else erros.add(info.id);estado.erros=[...erros];estado.temMais=Object.values(estado.porFonte).some(v=>v?.temMais);renderizarBuscaLogo();
 };
 try{
  const resposta=await pesquisarAcervo(q,{...opcoes(),fontesAtivas,aoFonte:aplicarFonte});if(token!==estado.token)return;
  const mapa=new Map(estado.livros.map(l=>[l.id,l]));for(const l of resposta.livros)if(l?.id&&!mapa.has(l.id))mapa.set(l.id,l);estado.livros=[...mapa.values()];
  estado.erros=[...new Set(resposta.erros)];
  for(const [id,dados] of Object.entries(resposta.porFonte||{})){const anterior=mais?porFonteAntes[id]:null;estado.porFonte[id]={...dados,carregados:(anterior?.carregados||0)+(dados.carregados||0)}}
  estado.temMais=Object.values(estado.porFonte).some(v=>v?.temMais);
 }catch{if(!estado.livros.length)estado.erros=['Fontes indisponíveis'];estado.temMais=Object.values(estado.porFonte).some(v=>v?.temMais)}
 if(token!==estado.token)return;estado.buscando=false;renderizar();
}
const buscaInicio=$('#busca-inicio');if(buscaInicio)buscaInicio.addEventListener('submit',e=>{e.preventDefault();abrirBusca($('#termo-inicio')?.value.trim()||'')});$('#form-busca').addEventListener('submit',e=>{e.preventDefault();executarBusca($('#campo-busca').value.trim())});$('#carregar-mais').addEventListener('click',()=>{if(estado.temMais&&!estado.buscando)executarBusca(estado.consulta,true)});const observadorMais=new IntersectionObserver(entradas=>{if(entradas.some(e=>e.isIntersecting)&&estado.temMais&&!estado.buscando&&$('#busca').open)executarBusca(estado.consulta,true)},{root:null,rootMargin:'600px 0px 600px 0px',threshold:0});observadorMais.observe($('#carregar-mais'));
function alternarAcervo(livro){const i=estado.acervo.findIndex(l=>l.id===livro.id);if(i>=0){estado.acervo.splice(i,1);aviso('Livro removido do acervo.')}else{estado.acervo.unshift({...livro,adicionadoEm:Date.now()});aviso('Livro guardado neste dispositivo.')}if(!gravar('bl:acervo',estado.acervo))aviso('O navegador não permitiu salvar. O acervo ficará apenas nesta sessão.');atualizarPerfil();if($('#busca').open)renderizar()}
function mostrarPainel(html){$('#conteudo-painel').innerHTML=html;abrir('painel');$('#painel > .fechar').focus()}
function ficha(l){mostrarPainel(`${img(l.capa,'ficha-capa','Capa de '+l.titulo)}<p class="rotulo">FICHA DA OBRA</p><h2>${escapar(l.titulo)}</h2><p>${escapar(l.autores?.join(' · ')||'')}</p>${l.descricao?`<p>${escapar(l.descricao)}</p>`:''}<dl class="detalhes"><div><dt>Acesso</dt><dd>${escapar(l.licenca||'Leitura gratuita disponibilizada pela fonte.')}</dd></div><div><dt>Fonte desta edição</dt><dd><a href="${escapar(linkSeguro(l.origem||l.ler))}" target="_blank" rel="noopener noreferrer">${escapar(l.provedor)} ↗</a></dd></div><div><dt>Idioma</dt><dd>${escapar(l.idiomas.join(', '))}</dd></div><div><dt>Disponibilidade</dt><dd>Os direitos e os formatos correspondem à edição da fonte. Traduções e outras edições podem ter condições diferentes.</dd></div></dl><div class="grupo-acoes">${l.ler?'<button class="primario" id="ler-ficha">Ler esta edição ↗</button>':''}${l.formatos.map(f=>`<a class="secundario" href="${escapar(linkSeguro(f.url))}" target="_blank" rel="noopener noreferrer">${escapar(f.tipo)} ↓</a>`).join('')}</div>`);$('#ler-ficha')?.addEventListener('click',()=>abrirLeitor(l))}
function painelAcervo(){mostrarPainel(`<p class="rotulo">MEU ACERVO</p><h2>Ideias que você<br>leva consigo.</h2><p>Seus livros ficam guardados neste dispositivo.</p>${estado.acervo.length?`<div class="lista-painel">${estado.acervo.map((l,i)=>`<div class="item-painel">${img(l.capa,'','')}<button data-acervo-ler="${i}"><strong>${escapar(l.titulo)}</strong><small>${escapar(l.autores?.join(', ')||'')} · abrir leitura</small></button><button class="remover" data-acervo-remover="${i}" aria-label="Remover ${escapar(l.titulo)}">×</button></div>`).join('')}</div>`:'<p>Seu acervo está esperando a primeira descoberta. Use “+ Acervo” nos resultados para guardar uma obra.</p><button class="primario" data-acao="explorar">Pesquisar no acervo ↗</button>'}`)}
function painelRecentes(){const recentes=Object.values(estado.progresso).filter(r=>r.livro).sort((a,b)=>b.abertoEm-a.abertoEm).slice(0,15);mostrarPainel(`<p class="rotulo">CONTINUAR LENDO</p><h2>A próxima página<br>está à sua espera.</h2>${recentes.length?`<div class="lista-painel">${recentes.map((r,i)=>`<div class="item-painel"><button data-recente="${i}"><strong>${escapar(r.livro.titulo)}</strong><small>${Math.round((r.fracao||0)*100)}% lido · continuar</small></button></div>`).join('')}</div>`:'<p>Abra uma leitura. O livro e seu progresso aparecerão aqui.</p><button class="primario" data-acao="explorar">Encontrar uma leitura ↗</button>'}`);document.querySelectorAll('[data-recente]').forEach(b=>b.addEventListener('click',()=>abrirLeitor(recentes[Number(b.dataset.recente)].livro)))}
function painelBichinho(){const l=estado.destaques.find(l=>l.tipo==='autor');mostrarPainel(`${l?img(l.capa,'ficha-capa','Capa real de Todo Dia um Bichinho Some'):''}<p class="rotulo">DO AUTOR DA BIBLIOTECA</p><h2>Todo Dia um<br>Bichinho Some</h2><p>Emeric</p><p>Uma pequena formiga em uma antiga casa. Uma vida quase invisível, que também merece ser vista.</p><blockquote>Uma biblioteca aberta também abre espaço para as vidas que o mundo insiste em ignorar.</blockquote><p>Esta obra autoral é apresentada aqui como destaque. Não há uma edição gratuita confirmada para leitura ou download.</p><a class="primario" href="https://www.amazon.com.br/Todo-Dia-um-Bichinho-Some-ebook/dp/B0GPVX2NDS" target="_blank" rel="noopener noreferrer">Conhecer a edição do autor ↗</a>`)}
async function painelDestaques(){await carregamento;const itens=estado.destaques.map((l,i)=>`<button class="destaque-painel" data-destaque="${i}" aria-label="${escapar(l.titulo)}: ${l.tipo==='autor'?'conhecer a obra do autor':'abrir destaque'}">${img(l.capa,'capa-destaque','Capa de '+l.titulo)}<span><strong>${escapar(l.titulo)}</strong><small>${l.tipo==='autor'?'Do autor da biblioteca':l.catalogoId?'Leitura gratuita':'Encontrar edição gratuita'}</small></span><b>↗</b></button>`).join('');mostrarPainel(`<p class="rotulo">LEITURAS QUE ABREM CAMINHOS</p><h2>Coleções em<br>destaque.</h2><p>A seleção saiu do centro da cena para que as críticas do ambiente possam ser lidas sem sobreposição.</p><div class="destaques-painel">${itens||'<p>Os destaques não puderam ser carregados agora.</p>'}</div>`)}
function painel(tipo){if(tipo==='acervo')return painelAcervo();if(tipo==='leitor')return painelRecentes();if(tipo==='bichinho')return painelBichinho();if(tipo==='destaques')return painelDestaques();if(tipo==='manifesto')return mostrarPainel(`<p class="rotulo">MANIFESTO DA BIBLIOTECA LIVRE</p><h2>Conhecimento<br>não é mercadoria.</h2><p>Quando o acesso ao saber depende do saldo bancário, a desigualdade deixa de ser um acidente. Torna-se um projeto que se reproduz a cada porta fechada.</p><blockquote>Mais bibliotecas.<br>Menos catracas.</blockquote><p>Uma educação organizada apenas para o mercado forma mão de obra antes de formar pessoas livres. A escola pública brasileira merece estrutura, livros, professores valorizados e tempo para pensar. Não merece o abandono disfarçado de mérito individual.</p><p>Não há igualdade de oportunidades entre quem herda uma biblioteca e quem precisa escolher entre o livro e o almoço. A meritocracia apaga o ponto de partida para chamar o privilégio de conquista.</p><p>Defendemos o conhecimento como bem comum: produzido por muitas mãos, compartilhado por muitas mentes. Cooperação, solidariedade e acesso universal são escolhas políticas.</p><blockquote>O futuro não pode<br>ser privatizado.</blockquote><p>Ler não transforma o mundo sozinho. Mas ajuda a reconhecer as estruturas que precisam mudar — e a imaginar, coletivamente, o que pode existir em seu lugar.</p><p class="rotulo">BIBLIOTECA LIVRE · O SABER É UM BEM COMUM</p>`);
if(tipo==='sobre')return mostrarPainel(`<p class="rotulo">SOBRE & FONTES</p><h2>Um acervo aberto.<br>Um direito comum.</h2><p>A Biblioteca Livre pesquisa 16 fontes conectadas de livros, acervos históricos, obras acadêmicas, artigos científicos e materiais educacionais. A pesquisa não restringe idioma, assunto ou plataforma.</p><p>Cada resultado informa o tipo de acesso. “Leitura integral” indica uma edição que a fonte permite ler por completo; “Prévia”, “Empréstimo” e “Catálogo” são mostrados como tal, sem serem apresentados como acesso integral. PDF e EPUB aparecem somente quando a fonte oferece o arquivo. No leitor de texto, “PDF” abre a impressão para salvar uma cópia.</p><div class="fontes-lista"><a href="https://www.gutenberg.org/" target="_blank" rel="noopener noreferrer">Project Gutenberg ↗</a><a href="https://openlibrary.org/" target="_blank" rel="noopener noreferrer">Open Library ↗</a><a href="https://books.google.com/" target="_blank" rel="noopener noreferrer">Google Books ↗</a><a href="https://pt.wikisource.org/" target="_blank" rel="noopener noreferrer">Wikisource ↗</a><a href="https://archive.org/" target="_blank" rel="noopener noreferrer">Internet Archive ↗</a><a href="https://library.oapen.org/" target="_blank" rel="noopener noreferrer">OAPEN — livros acadêmicos abertos ↗</a><a href="https://directory.doabooks.org/" target="_blank" rel="noopener noreferrer">DOAB — livros acadêmicos abertos ↗</a><a href="https://europepmc.org/" target="_blank" rel="noopener noreferrer">Europe PMC — artigos científicos abertos ↗</a><a href="https://eric.ed.gov/" target="_blank" rel="noopener noreferrer">ERIC — pesquisa e materiais educacionais ↗</a><a href="https://www.ncbi.nlm.nih.gov/books/" target="_blank" rel="noopener noreferrer">NCBI Bookshelf — livros de saúde e ciências da vida ↗</a><a href="https://arxiv.org/" target="_blank" rel="noopener noreferrer">arXiv — preprints e artigos acadêmicos em PDF ↗</a><a href="https://doaj.org/" target="_blank" rel="noopener noreferrer">DOAJ — periódicos e artigos de acesso aberto ↗</a><a href="https://pt.wikibooks.org/" target="_blank" rel="noopener noreferrer">Wikibooks — livros didáticos e apostilas ↗</a><a href="https://pt.wikiversity.org/" target="_blank" rel="noopener noreferrer">Wikiversidade — materiais de estudo ↗</a><a href="https://www.loc.gov/" target="_blank" rel="noopener noreferrer">Library of Congress ↗</a><a href="https://gallica.bnf.fr/" target="_blank" rel="noopener noreferrer">Gallica · BnF ↗</a></div><p>As próprias APIs dividem catálogos grandes em páginas; a biblioteca continua carregando páginas conforme você rola, sem impor um corte artificial de resultados. A disponibilidade de uma edição ainda pode variar por país ou pela própria fonte.</p><h3>Seu espaço de leitura</h3><p>Perfil, acervo e progresso são salvos apenas neste navegador. Não há senha, assinatura ou sincronização entre aparelhos. Ao pesquisar ou abrir uma edição externa, seu navegador se conecta à fonte escolhida.</p><p>Capas: edições identificadas nos catálogos e na página comercial do autor. O cenário é uma criação visual; as críticas do manifesto são textos próprios desta biblioteca.</p>`);
if(tipo==='colecoes')return mostrarPainel(`<p class="rotulo">COLEÇÕES</p><h2>Diferentes portas.<br>Outros mundos.</h2><div class="lista-painel">${Object.entries(temas).map(([id,t])=>`<div class="item-painel"><button data-categoria="${id}"><strong>${t.nome}</strong><small>Pesquisar obras relacionadas ↗</small></button></div>`).join('')}</div><div class="item-painel"><button data-painel="bichinho"><strong>Todo Dia um Bichinho Some</strong><small>Conheça o livro do autor da biblioteca ↗</small></button></div>`);
if(tipo==='menu')return mostrarPainel(`<p class="rotulo">BIBLIOTECA LIVRE</p><h2>Entre. O saber<br>é de todos.</h2><nav class="lista-painel" aria-label="Navegação"><div class="item-painel"><button data-acao="inicio"><strong>Início</strong></button></div><div class="item-painel"><button data-acao="explorar"><strong>Explorar</strong></button></div><div class="item-painel"><button data-painel="destaques"><strong>Destaques</strong></button></div><div class="item-painel"><button data-acao="dominio"><strong>Domínio público</strong></button></div>${[['colecoes','Coleções'],['acervo','Meu acervo'],['leitor','Continuar lendo'],['bichinho','Todo Dia um Bichinho Some'],['manifesto','Manifesto'],['sobre','Sobre & fontes'],['preferencias','Som e movimento']].map(([id,t])=>`<div class="item-painel"><button data-painel="${id}"><strong>${t}</strong></button></div>`).join('')}</nav>`);
if(tipo==='perfil'){mostrarPainel(`<p class="rotulo">SEU ESPAÇO</p><h2>Como podemos<br>chamar você?</h2><p>Um perfil local para acompanhar sua leitura. Seu nome fica apenas neste navegador.</p><form id="form-perfil" class="form-perfil"><label for="nome-perfil">Seu nome</label><input id="nome-perfil" maxlength="50" autocomplete="given-name" value="${escapar(estado.perfil?.nome||'')}" required><button class="primario" type="submit">Salvar perfil</button></form>`);$('#form-perfil').addEventListener('submit',e=>{e.preventDefault();const nome=$('#nome-perfil').value.trim();if(!nome)return;estado.perfil={nome};const salvo=gravar('bl:perfil',estado.perfil);atualizarPerfil();fechar('painel');aviso(salvo?'Perfil salvo neste dispositivo.':'Perfil aplicado apenas nesta sessão.')});return}
if(tipo==='preferencias'){mostrarPainel(`<p class="rotulo">SEU RITMO</p><h2>Uma pausa<br>também é leitura.</h2><label class="opcao-preferencia">Pausar o movimento<input id="preferencia-pausa" type="checkbox" ${estado.pausado?'checked':''}></label><label class="opcao-preferencia">Som suave do oceano<input id="preferencia-som" type="checkbox" ${estado.audio?.ativo?'checked':''}></label><label class="opcao-preferencia">Detalhes do cenário<select id="qualidade"><option value="economia">Leve</option><option value="equilibrado">Equilibrado</option><option value="cinematografico">Mais detalhes</option></select></label><p>O som começa apenas quando você o ativa. Essas preferências e seu progresso ficam neste dispositivo.</p>`);$('#qualidade').value=estado.qualidade;$('#preferencia-pausa').addEventListener('change',e=>definirPausa(e.target.checked));$('#preferencia-som').addEventListener('change',alternarSom);$('#qualidade').addEventListener('change',e=>{estado.qualidade=e.target.value;gravar('bl:qualidade',estado.qualidade);cenario.qualidade(estado.qualidade)});return}}
async function abrirLeitor(l){if(!l?.ler)return;salvarLeitura();const t=++estado.leituraToken;estado.leitura=l;const progresso=estado.progresso[l.id];$('#titulo-leitor').textContent=l.titulo;$('#corpo-leitor').textContent='Preparando seu livro…';$('#corpo-leitor').style.setProperty('--tamanho-leitor',`${estado.fonte}px`);$('#leitor').classList.toggle('tema-escuro',lerSalvo('bl:tema-leitor',false));$('#imprimir').hidden=true;$('#fonte-menor').hidden=false;$('#fonte-maior').hidden=false;estado.restaurando=true;abrir('leitor');$('#leitor-rolagem').scrollTop=0;$('#progresso-leitura').value=0;$('#porcentagem-leitura').textContent='0%';try{if(!l.texto)throw Error('fonte');const c=new AbortController();const timer=setTimeout(()=>c.abort(),12000);let r;try{r=await fetch(l.texto,{signal:c.signal})}finally{clearTimeout(timer)}if(!r.ok)throw Error();let texto=await r.text();if(t!==estado.leituraToken)return;if(texto.length>5000000||/<html[\s>]/i.test(texto.slice(0,500)))throw Error();const ini=texto.match(/\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG EBOOK[^\n]*\n/i);const fim=texto.search(/\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG EBOOK/i);if(ini&&fim>ini.index)texto=texto.slice(ini.index+ini[0].length,fim);$('#corpo-leitor').textContent=texto.replace(/\r/g,'').trim();$('#imprimir').hidden=false;requestAnimationFrame(()=>{if(t!==estado.leituraToken)return;const s=$('#leitor-rolagem');s.scrollTop=(progresso?.fracao||0)*(s.scrollHeight-s.clientHeight);estado.restaurando=false;salvarLeitura()})}catch{if(t!==estado.leituraToken)return;$('#corpo-leitor').innerHTML=`<p>Esta edição é lida gratuitamente no site da fonte.</p><p><a class="primario" href="${escapar(linkSeguro(l.ler))}" target="_blank" rel="noopener noreferrer">Abrir ${escapar(l.provedor)} ↗</a></p><p>O progresso da leitura externa é controlado pela própria fonte.</p>`;$('#fonte-menor').hidden=true;$('#fonte-maior').hidden=true;estado.restaurando=false;salvarLeitura(true)}}
function salvarLeitura(externo=false){if(!estado.leitura||estado.restaurando)return;const s=$('#leitor-rolagem');const fracao=externo?0:(s.scrollHeight>s.clientHeight?Math.min(1,s.scrollTop/(s.scrollHeight-s.clientHeight)):0);estado.progresso[estado.leitura.id]={livro:estado.leitura,fracao,externo,abertoEm:Date.now()};gravar('bl:progresso',estado.progresso);$('#progresso-leitura').value=fracao*100;$('#porcentagem-leitura').textContent=Math.round(fracao*100)+'%'}
let temporizador;$('#leitor-rolagem').addEventListener('scroll',()=>{clearTimeout(temporizador);temporizador=setTimeout(()=>salvarLeitura(),160)},{passive:true});addEventListener('pagehide',()=>salvarLeitura());for(const [id,v] of [['fonte-menor',-1],['fonte-maior',1]])$('#'+id).addEventListener('click',()=>{estado.fonte=Math.min(34,Math.max(16,estado.fonte+v));$('#corpo-leitor').style.setProperty('--tamanho-leitor',`${estado.fonte}px`);gravar('bl:fonte',estado.fonte)});$('#tema-leitor').addEventListener('click',()=>gravar('bl:tema-leitor',$('#leitor').classList.toggle('tema-escuro')));$('#imprimir').addEventListener('click',()=>window.print());
async function alternarSom(){try{if(!estado.audio){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error();const ctx=new AC(),buffer=ctx.createBuffer(1,ctx.sampleRate*4,ctx.sampleRate),d=buffer.getChannelData(0);let anterior=0;for(let i=0;i<d.length;i++){anterior=(anterior+.02*(Math.random()*2-1))/1.02;d[i]=anterior*3.5}const fonte=ctx.createBufferSource(),filtro=ctx.createBiquadFilter(),ganho=ctx.createGain();fonte.buffer=buffer;fonte.loop=true;filtro.type='lowpass';filtro.frequency.value=700;ganho.gain.value=0;fonte.connect(filtro).connect(ganho).connect(ctx.destination);fonte.start();estado.audio={ctx,ganho,ativo:false}}const a=estado.audio;await a.ctx.resume();a.ativo=!a.ativo;a.ganho.gain.setTargetAtTime(a.ativo?.12:0,a.ctx.currentTime,.6);$('#botao-som').setAttribute('aria-pressed',String(a.ativo));$('#botao-som').setAttribute('aria-label',a.ativo?'Desativar som do oceano':'Ativar som do oceano')}catch{aviso('O som não está disponível neste navegador.')}}
$('#botao-som').addEventListener('click',alternarSom);$('#botao-movimento').addEventListener('click',()=>definirPausa(!estado.pausado));
document.addEventListener('click',async e=>{const b=e.target.closest('button,a[data-fechar]');if(!b)return;if(b.dataset.fechar){e.preventDefault();fechar(b.dataset.fechar);return}if(b.dataset.painel)return painel(b.dataset.painel);if(b.dataset.acao){if($('#painel').open)fechar('painel');if(b.dataset.acao==='inicio'){for(const d of document.querySelectorAll('dialog[open]'))fechar(d.id);window.scrollTo({top:0,behavior:'smooth'})}else if(b.dataset.acao==='dominio'){abrirBusca('')}else{abrirBusca('')}return}if(b.dataset.categoria){if($('#painel').open)fechar('painel');const tema=temas[b.dataset.categoria];return abrirBusca(tema?.busca||tema?.nome||b.dataset.categoria)}if(b.hasAttribute('data-destaque')){const l=estado.destaques[Number(b.dataset.destaque)];if(l.tipo==='autor')return painelBichinho();const local=estado.catalogo.find(x=>x.id===l.catalogoId);if(local)return ficha(local);return abrirBusca(l.consulta||l.titulo)}if(b.hasAttribute('data-ler'))return abrirLeitor(estado.resultados[Number(b.dataset.ler)]);if(b.hasAttribute('data-salvar'))return alternarAcervo(estado.resultados[Number(b.dataset.salvar)]);if(b.hasAttribute('data-ficha'))return ficha(estado.resultados[Number(b.dataset.ficha)]);if(b.hasAttribute('data-acervo-ler'))return abrirLeitor(estado.acervo[Number(b.dataset.acervoLer)]);if(b.hasAttribute('data-acervo-remover')){alternarAcervo(estado.acervo[Number(b.dataset.acervoRemover)]);return painelAcervo()}if(b.hasAttribute('data-repetir-busca')){executarBusca(estado.consulta);return}if(b.hasAttribute('data-ver-selecao')){abrirBusca('')}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'')&&!$('#leitor').open){e.preventDefault();abrirBusca('')}});
if('serviceWorker'in navigator)navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>{if(r.scope===location.origin+'/')r.unregister()})).catch(()=>{});
